constraints:
1 <= N <= 10^{6}
1 <= K <= 10^{6}

expected time complexity: O(sqrt(N))
expected auxiliary space: O(1)

standard_solution_code:
class Solution:

	def kThSmallestFactor(self, N, K):
		factors = []
		for i in range(1, int(N ** 0.5) + 1):
			if N % i == 0:
				factors.append(i)
				if i != N // i:
					factors.append(N // i)
		factors.sort()
		if K > len(factors):
			return -1
		else:
			return factors[K - 1]
